cssCode:
.luxury-card {
  width: 200px; height: 260px;
  background: rgba(255, 255, 255, 0.05);
  backdrop-filter: blur(15px);
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 15px; position: relative; overflow: hidden;
  box-shadow: 0 15px 35px rgba(0,0,0,0.5);
  display: flex; align-items: flex-end; padding: 20px;
  color: #fff; font-family: sans-serif; font-weight: bold;
  transition: transform 0.4s ease; cursor: pointer;
}
.luxury-card::before {
  content: ""; position: absolute; top: 0; left: -100%;
  width: 50%; height: 100%;
  background: linear-gradient(to right, transparent, rgba(255,255,255,0.3), transparent);
  transform: skewX(-25deg); transition: left 0.6s ease;
}
.luxury-card:hover, .luxury-card:active { transform: translateY(-10px); }
.luxury-card:hover::before, .luxury-card:active::before { left: 200%; }

